import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Attachment — a file card, one of this library's chat primitives.
 *
 *   <AttachmentGroup>                          scrollable, snapping row
 *     <Attachment orientation="vertical" size="sm" state="uploading">
 *       <AttachmentTrigger href="…" />         fills the card behind the actions
 *       <AttachmentMedia variant="image"><img …/></AttachmentMedia>
 *       <AttachmentContent>
 *         <AttachmentTitle>report.pdf</AttachmentTitle>
 *         <AttachmentDescription>2.4 MB</AttachmentDescription>
 *       </AttachmentContent>
 *       <AttachmentActions>
 *         <AttachmentAction>…</AttachmentAction>
 *       </AttachmentActions>
 *     </Attachment>
 *   </AttachmentGroup>
 *
 * Geometry: p 8, gap 8, rounded-2xl (18), 1px border on `card`.
 * `state` reflects the upload lifecycle — uploading and processing shimmer the
 * title, error switches the card to a destructive treatment.
 */
const attachmentVariants = cva(
  "relative flex gap-2 rounded-2xl border bg-card p-2 text-sm text-card-foreground",
  {
    variants: {
      orientation: {
        horizontal: "w-full flex-row items-center",
        vertical: "w-30 flex-col items-stretch",
      },
      size: { default: "text-sm", sm: "text-sm", xs: "gap-1.5 p-1.5 text-xs" },
      state: {
        idle: "",
        uploading: "[&_[data-slot=attachment-title]]:animate-pulse",
        processing: "[&_[data-slot=attachment-title]]:animate-pulse",
        error: "border-destructive/40 bg-destructive-subtle text-text-destructive",
      },
    },
    defaultVariants: { orientation: "horizontal", size: "default", state: "idle" },
  }
);

const AttachmentContext = React.createContext<{ size: "default" | "sm" | "xs" }>({
  size: "default",
});

function Attachment({
  className,
  orientation,
  size,
  state,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof attachmentVariants>) {
  return (
    <AttachmentContext.Provider value={{ size: size ?? "default" }}>
      <div
        data-slot="attachment"
        data-orientation={orientation ?? "horizontal"}
        data-state={state ?? "idle"}
        className={cn(attachmentVariants({ orientation, size, state }), className)}
        {...props}
      />
    </AttachmentContext.Provider>
  );
}

/** Lays attachments out in a horizontally scrollable, snapping row with an edge fade. */
function AttachmentGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-group"
      className={cn(
        "relative flex snap-x snap-mandatory gap-2 overflow-x-auto scroll-smooth",
        "[&>[data-slot=attachment]]:snap-start [&>[data-slot=attachment]]:shrink-0",
        "[mask-image:linear-gradient(to_right,black_calc(100%-2rem),transparent)]",
        className
      )}
      {...props}
    />
  );
}

/**
 * Fills the card behind the actions so the whole card opens a link or dialog
 * while the actions stay clickable.
 */
function AttachmentTrigger({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"a"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "a";
  return (
    <Comp
      data-slot="attachment-trigger"
      className={cn(
        "absolute inset-0 z-0 rounded-2xl",
        "focus-visible:ring-ring-subtle focus-visible:ring-[3px] focus-visible:outline-none",
        className
      )}
      {...props}
    />
  );
}

const attachmentMediaVariants = cva(
  "relative z-[1] flex shrink-0 items-center justify-center overflow-hidden rounded-lg [&_svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "bg-muted text-foreground",
        icon: "bg-muted text-foreground",
        image: "bg-muted [&_img]:size-full [&_img]:object-cover",
      },
      size: {
        default: "size-10 [&_svg:not([class*='size-'])]:size-5",
        sm: "size-8 [&_svg:not([class*='size-'])]:size-4",
        xs: "size-7 [&_svg:not([class*='size-'])]:size-3.5",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
);

function AttachmentMedia({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof attachmentMediaVariants>) {
  const ctx = React.useContext(AttachmentContext);
  return (
    <div
      data-slot="attachment-media"
      className={cn(attachmentMediaVariants({ variant, size: size ?? ctx.size }), className)}
      {...props}
    />
  );
}

function AttachmentContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-content"
      className={cn("relative z-[1] flex min-w-0 flex-1 flex-col gap-0.5", className)}
      {...props}
    />
  );
}

function AttachmentTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-title"
      className={cn("truncate font-medium", className)}
      {...props}
    />
  );
}

function AttachmentDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-description"
      className={cn("truncate text-xs text-muted-foreground", className)}
      {...props}
    />
  );
}

function AttachmentActions({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-actions"
      className={cn("relative z-[1] flex shrink-0 items-center gap-1", className)}
      {...props}
    />
  );
}

function AttachmentAction({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      type={asChild ? undefined : "button"}
      data-slot="attachment-action"
      className={cn(
        "inline-flex size-7 items-center justify-center rounded-md transition-colors",
        "hover:bg-accent hover:text-accent-foreground",
        "focus-visible:ring-ring-subtle focus-visible:ring-[3px] focus-visible:outline-none",
        "[&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    />
  );
}

export {
  Attachment,
  AttachmentGroup,
  AttachmentTrigger,
  AttachmentMedia,
  AttachmentContent,
  AttachmentTitle,
  AttachmentDescription,
  AttachmentActions,
  AttachmentAction,
  attachmentVariants,
  attachmentMediaVariants,
};
